{
  "summary": "The candidate demonstrates strong, quantifiable technical depth in Data Engineering, successfully handling high-scale data pipelines and optimizing complex systems. However, the resume explicitly targets a Frontend Engineer role, which is a significant mismatch with the experience detailed.",
  "wouldAdvance": "maybe",
  "strengths": [
    {
      "point": "Demonstrates high-impact performance optimization on large-scale jobs.",
      "evidence": "Rewrote a slow Spark job so a 6-hour aggregation finishes in 50 minutes, saving about $3,000 a month in compute."
    },
    {
      "point": "Has experience designing and implementing modern data modeling layers.",
      "evidence": "Designed a dbt model layer of 85 tables with tests, replacing 30 hand-written SQL reports."
    },
    {
      "point": "Successfully built and managed high-volume data ingestion pipelines.",
      "evidence": "Built Airflow pipelines that load 40 million events a day into Snowflake, cutting nightly job failures from 12 a week to 1."
    },
    {
      "point": "Shows experience with real-time data processing and quality control.",
      "evidence": "Built a Kafka consumer that deduplicates 2 million records a day with under 0.01% loss."
    },
    {
      "point": "Has leadership experience in technical mentorship.",
      "evidence": "Mentored 3 analysts on SQL performance and partitioning."
    }
  ],
  "issues": [
    {
      "severity": "high",
      "problem": "The resume claims to be targeting a Frontend role, but all experience is in Data Engineering.",
      "evidence": "Frontend engineer with 6 years of experience building fast, accessible React interfaces.",
      "suggestion": "If applying for a Data Engineering role, change the summary to reflect Data Engineering expertise. If applying for a Frontend role, provide relevant React/UI experience."
    },
    {
      "severity": "medium",
      "problem": "The listed skills include React, but there is no supporting evidence in the work experience.",
      "evidence": "React",
      "suggestion": "If React skills are relevant to the target role, provide specific examples of how they were used in the experience section."
    }
  ]
}
